insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, published_at) values ('article', 'maldives-fishing-seasons-month-by-month-guide', 'Maldives Fishing Seasons: A Month-by-Month Guide', 'When to target which species around the Maldives'' atolls, from the northeast monsoon''s tuna and wahoo run to the giant trevally season that follows it.', 'published', 'Maldives Fishing Seasons: A Month-by-Month Guide | Maldives Travel Guide | MTG', 'When to target which species around the Maldives'' atolls, from the northeast monsoon''s tuna and wahoo run to the giant trevally season that follows it.', now()) on conflict (node_type, slug) do nothing;
insert into articles (id, body, reading_time_minutes) select id, '<p>Fishing conditions around the Maldives change with the country''s two monsoon seasons, and several of the species anglers travel here for have a season of their own inside that pattern. This guide sets out what''s realistically most productive when, drawing on the same species data used throughout our <a href="/maldives/fishing/">Maldives fishing guide</a>.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-liveaboard-maldives.webp" alt="Fishing liveaboard in the Maldives" loading="lazy" /></figure><h2>The two monsoons</h2><p>The Maldives sits in a tropical monsoon climate with two broad seasons. The northeast monsoon, locally called Iruvai, runs roughly from December to April and brings calmer seas and less rain — the more predictable window for boat trips of any kind. The southwest monsoon, Hulhangu, runs roughly from May to November, with more rain and rougher water on any given day, though trips still go out throughout it and some of the best sport-fishing species are more active during this period.</p><h2>Best season by species</h2><p>These are the seasonal patterns behind the species covered in our <a href="/maldives/fishing/#fish-species">fish species guide</a>:</p><ul><li><strong>Yellowfin Tuna</strong> — December to March, during the calmer northeast monsoon.</li><li><strong>Wahoo</strong> — December to March, the same window, and typically caught by trolling.</li><li><strong>Mahi-Mahi</strong> — December to April, often around floating debris and FADs (fish aggregating devices).</li><li><strong>Dogtooth Tuna</strong> — November to April, on the deeper reef slopes and drop-offs.</li><li><strong>Giant Trevally</strong> — April to October, spanning the shift into the southwest monsoon.</li><li><strong>Skipjack Tuna</strong> — year-round, the backbone of the Maldives'' traditional pole-and-line fishing industry.</li></ul><h2>December to April: the northeast monsoon run</h2><p>This is the window when yellowfin tuna, wahoo and mahi-mahi are all in season together, and calmer seas make for more comfortable days on the water and better trolling conditions along the atoll edges.</p><figure><img src="legacy/fishing/images/yellowfin-tuna.webp" alt="Yellowfin Tuna in the Maldives" loading="lazy" /></figure><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo in the Maldives" loading="lazy" /></figure><h2>April to October: giant trevally season</h2><p>As the season shifts toward the southwest monsoon, giant trevally move into season. GT are considered the Maldives'' signature sport-fishing target, patrolling reef edges and channels and known for explosive strikes — the country is rated among the best destinations worldwide for trophy-sized GT.</p><figure><img src="legacy/images/fishing/giant-trevally-fish.webp" alt="Giant Trevally in the Maldives" loading="lazy" /></figure><h2>Booking around the season</h2><p><a href="/maldives/providers/maldives-fishing-and-holiday/">Maldives Fishing and Holiday Pvt Ltd</a> runs private charters from Maamendhoo in Gaafu Alifu Atoll year-round aboard its boat "Emperor" — see our <a href="/maldives/fishing/private-full-day-fishing-charter/">full-day</a> and <a href="/maldives/fishing/private-half-day-fishing-charter/">half-day charter</a> pages for current pricing, or read the full writeup in our <a href="/maldives/travel-guide/gaafu-atoll-fishing-guide-mfh-maamendhoo/">Gaafu Atoll fishing guide</a>.</p>', 6 from nodes where node_type = 'article' and slug = 'maldives-fishing-seasons-month-by-month-guide' on conflict (id) do nothing;
