insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, published_at) values ('article', 'maldives-fishing-techniques-guide', 'Maldives Fishing Techniques: Trolling, Jigging, Popping and Handline Fishing Explained', 'A plain guide to the main fishing techniques used around Maldivian atolls — trolling, jigging, popping and handline fishing — and which species each one targets.', 'published', 'Maldives Fishing Techniques: Trolling, Jigging, Popping and Handline Fishing Explained | Maldives Travel Guide | MTG', 'A plain guide to the main fishing techniques used around Maldivian atolls — trolling, jigging, popping and handline fishing — and which species each one targets.', now()) on conflict (node_type, slug) do nothing;
insert into articles (id, body, reading_time_minutes) select id, '<p>Most fishing trips booked in the Maldives fall into one of a handful of techniques, each suited to different species and different stretches of water. This guide explains what each one involves and what you''re likely to be fishing for.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/maldives-atoll-aerial-view.webp" alt="Maldives atoll aerial view" loading="lazy" /></figure><h2>Trolling</h2><p>Trolling means running lines with lures or bait behind a moving boat, typically along the edges of an atoll or a reef drop-off where pelagic fish pass by. It''s the standard technique for wahoo — among the fastest fish in the ocean, capable of speeds up to 80 km/h — and is also used for yellowfin tuna and mahi-mahi, which are often found near floating debris.</p><figure><img src="legacy/fishing/images/wahoo-in-maldives.webp" alt="Wahoo in the Maldives" loading="lazy" /></figure><h2>Jigging</h2><p>Jigging works a weighted metal lure vertically near the bottom, over deep reef slopes and drop-offs rather than the open water trolling covers. It''s the method most associated with dogtooth tuna, a solitary, hard-fighting predator that lives on exactly this kind of structure.</p><figure><img src="legacy/fishing/images/dogtooth-tuna-in-maldives.webp" alt="Dogtooth Tuna in the Maldives" loading="lazy" /></figure><h2>Popping</h2><p>Popping casts a surface lure toward reef edges and channels and retrieves it in sharp, splashing bursts to draw a strike from the surface rather than the depths. It''s the technique most closely tied to giant trevally, which the Maldives is internationally rated among the best destinations to target.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/giant-trevally.webp" alt="Giant trevally caught fishing in the Maldives" loading="lazy" /></figure><h2>Handline and bottom fishing</h2><p>Handline fishing — a reel, line, hook and bait, worked by hand rather than cast and retrieved — is the traditional, lowest-barrier technique, commonly offered as an introductory sunset trip and requiring no prior experience. It''s also the basis of the Maldives'' historic pole-and-line skipjack tuna industry. Bottom fishing, a closely related technique fished at anchor over reef structure, is the usual way to target groupers and snappers.</p><figure><img src="legacy/images/fishing/tuna-fish-in-maldives.webp" alt="Skipjack Tuna in the Maldives" loading="lazy" /></figure><figure><img src="uploads/assets/uploads/fishing/images/gallery/reef-fishing-grouper.webp" alt="Reef fishing grouper in the Maldives" loading="lazy" /></figure><h2>Choosing a technique</h2><p>If you want an easy, sociable first trip, a handline or sunset trip needs no experience. If you''re after a specific trophy species, the technique follows the fish: trolling for wahoo and tuna, jigging for dogtooth tuna, popping for giant trevally. <a href="/maldives/providers/maldives-fishing-and-holiday/">Maldives Fishing and Holiday Pvt Ltd</a>''s private charters out of Maamendhoo cover trolling and bottom fishing aboard "Emperor" — see our <a href="/maldives/fishing/private-full-day-fishing-charter/">full-day charter</a> page, or browse the full <a href="/maldives/fishing/#fish-species">fish species guide</a> for more on what you might catch.</p>', 6 from nodes where node_type = 'article' and slug = 'maldives-fishing-techniques-guide' on conflict (id) do nothing;
