insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, published_at) values ('article', 'gaafu-atoll-fishing-guide-mfh-maamendhoo', 'Fishing in Gaafu Atoll: A Guide to Maldives Fishing and Holidays Lodge on Maamendhoo', 'The charter boat, pricing and multi-night packages run by Maldives Fishing and Holiday Pvt Ltd from its lodge on Maamendhoo, Gaafu Alifu Atoll.', 'published', 'Fishing in Gaafu Atoll: A Guide to Maldives Fishing and Holidays Lodge on Maamendhoo | Maldives Travel Guide | MTG', 'The charter boat, pricing and multi-night packages run by Maldives Fishing and Holiday Pvt Ltd from its lodge on Maamendhoo, Gaafu Alifu Atoll.', now()) on conflict (node_type, slug) do nothing;
insert into articles (id, body, reading_time_minutes) select id, '<p>Maamendhoo, an island in Gaafu Alifu Atoll in the southern Maldives, is home to Maldives Fishing and Holidays Lodge and the charter operation run alongside it, Maldives Fishing and Holiday Pvt Ltd (registration C40602025, managing director Safooh Ali). This guide covers the boat, the charter pricing and the multi-night packages built around it.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge.jpeg" alt="Maldives Fishing and Holidays Lodge, Maamendhoo, Gaafu Alifu Atoll" loading="lazy" /></figure><h2>The lodge</h2><p><a href="/maldives/guesthouses/maldives-fishing-and-holidays-lodge/">Maldives Fishing and Holidays Lodge</a> is a guesthouse on Maamendhoo with full-board rooms for up to 2 guests each, run by the same company that operates the fishing charters — so accommodation and fishing are booked from one operator rather than pieced together separately.</p><figure><img src="uploads/assets/uploads/hotels/maldives-fishing/maldives-fishing-and-holidays-lodge-hotel.jpeg" alt="Maldives Fishing and Holidays Lodge" loading="lazy" /></figure><h2>The boat</h2><p>Charters run aboard "Emperor", a 32-foot fishing boat with twin 200 HP outboard engines and a maximum capacity of 5 passengers.</p><figure><img src="uploads/assets/uploads/fishing/images/gallery/fishing-charter-boat.webp" alt="Fishing charter boat in the Maldives" loading="lazy" /></figure><h2>Private charter pricing</h2><p>Two private charters are bookable directly, priced per boat rather than per person:</p><ul><li><a href="/maldives/fishing/private-full-day-fishing-charter/">Private Full-Day Fishing Charter</a> — from USD 1,380 per boat, roughly 8 hours.</li><li><a href="/maldives/fishing/private-half-day-fishing-charter/">Private Half-Day Fishing Charter</a> — from USD 980 per boat, roughly 4 hours.</li></ul><h2>Multi-night fishing packages</h2><p>Beyond the two standalone charters, the operator runs 14 multi-night packages spanning 2 to 8 nights, each available in a full-day or half-day fishing format, bundling the lodge stay with a return domestic flight, boat transfer and the matching number of charter days. Pricing is tiered by group size from 1 to 5 guests sharing the boat, with 5 guests sharing the best per-person rate. The <a href="/maldives/packages/2-night-maldives-fishing-package-full-day-fishing/">2-night package</a> and <a href="/maldives/packages/8-night-maldives-fishing-package-full-day-fishing/">8-night package</a> mark the two ends of that range — see the full <a href="/maldives/packages/fishing/">fishing packages listing</a> for every duration.</p><h2>Getting there</h2><p>Packages built around Maamendhoo combine a return domestic flight with a boat transfer to the island, arranged as part of the package rather than booked separately.</p><h2>Booking</h2><p>All of the above are inquiry-based bookings — reach the operator through the <a href="/maldives/providers/maldives-fishing-and-holiday/">Maldives Fishing and Holiday Pvt Ltd</a> provider page, or start from whichever charter or package page fits your trip.</p>', 5 from nodes where node_type = 'article' and slug = 'gaafu-atoll-fishing-guide-mfh-maamendhoo' on conflict (id) do nothing;
